BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats2-q01', '確率と分布',
   '友だちが「明日の降水確率は70%だって」と教えてくれた。この「70%」のように、起こりやすさを0から1（または0%から100%）の数で表したものを何と呼ぶ？',
   NULL::text,
   '["確率", "分散", "偏差値", "度数"]',
   0, '[0]', 'single',
   '{"asked": "「起こりやすさ」を数字にする、という統計・確率の一番の入口。", "point": "絶対起きないなら0、絶対起きるなら1。そのあいだの「起きやすさ」を数で表したのが確率。", "kid": "サイコロで1の目が出るのも、明日雨が降るのも、「絶対」とは言い切れない。でも「起きやすさ」にはレベルがある。それを0（絶対起きない）から1（絶対起きる）までの数字に対応させたものが確率。", "eg": "やじろべえが真ん中で釣り合っているように、確率は「絶対に起きない」と「絶対に起きる」のあいだのどのあたりに傾いているかを示す数字。0.7なら、起きる側にかなり傾いている。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"14\" y=\"18\" width=\"46\" height=\"46\" rx=\"7\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"37\" cy=\"41\" r=\"3.2\" fill=\"#e8eaf0\"/><rect x=\"66\" y=\"18\" width=\"46\" height=\"46\" rx=\"7\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"80\" cy=\"32\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"98\" cy=\"50\" r=\"3.2\" fill=\"#e8eaf0\"/><rect x=\"118\" y=\"18\" width=\"46\" height=\"46\" rx=\"7\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"132\" cy=\"32\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"141\" cy=\"41\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"150\" cy=\"50\" r=\"3.2\" fill=\"#e8eaf0\"/><rect x=\"170\" y=\"18\" width=\"46\" height=\"46\" rx=\"7\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"184\" cy=\"32\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"202\" cy=\"32\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"184\" cy=\"50\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"202\" cy=\"50\" r=\"3.2\" fill=\"#e8eaf0\"/><rect x=\"222\" y=\"18\" width=\"46\" height=\"46\" rx=\"7\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"236\" cy=\"32\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"254\" cy=\"32\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"245\" cy=\"41\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"236\" cy=\"50\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"254\" cy=\"50\" r=\"3.2\" fill=\"#e8eaf0\"/><rect x=\"274\" y=\"18\" width=\"46\" height=\"46\" rx=\"7\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"288\" cy=\"30\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"306\" cy=\"30\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"288\" cy=\"41\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"306\" cy=\"41\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"288\" cy=\"52\" r=\"3.2\" fill=\"#e8eaf0\"/><circle cx=\"306\" cy=\"52\" r=\"3.2\" fill=\"#e8eaf0\"/><text x=\"170\" y=\"90\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">どの目も出やすさは同じ</text><text x=\"170\" y=\"112\" fill=\"#60a5fa\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"600\">1つの目が出る確率 ＝ 1/6</text><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">（6つの目のうち1つ、という比）</text></svg>", "terms": [["確率", "ある出来事の起きやすさを0〜1の数で表したもの"], ["試行", "サイコロを振る、コインを投げるなど、結果が偶然で決まる1回の行為"]], "think": "サイコロを振ったとき、1の目も2の目も6の目も、出やすさに差はない。全部で6通りの目があり、そのうちの1通りが「1の目」なので、1の目が出る確率は6つのうち1つ、という比で表す。この「何通りのうち何通りか」を数字に落とし込む考え方が、確率のすべての土台になる。", "vs": "分散や偏差値は「集めたデータのばらつきや位置」を表す数字で、まだ起きていない出来事の起きやすさとは別の話。確率は「これから起きるかもしれないこと」に使う数字。", "why_asked": "天気予報も保険も宝くじも、「絶対」とは言えない世界を相手にしている。「起きやすさ」を数字で扱えないと、これらを比べたり計算したりできない。確率は、その不確かさを数字に変える発明。", "usecase": "天気予報の降水確率、ゲームのガチャの排出率、保険料の計算、品質検査での不良品が混ざる確率。「たぶん」を数字にする場面すべて。", "opt": ["正解。起こりやすさを0〜1（0%〜100%）の数で表したものが確率。", "分散はデータの散らばりの大きさを表す数字で、これから起きる出来事の起きやすさとは別物。", "偏差値は平均を50としたテストの成績の位置を表す数字で、確率とは計算のしかたも意味も違う。", "度数はある値が何回・何個現れたかという回数で、割合や比ではなく実際に数えた個数のこと。"]}'),

  ('stats2-q02', '確率と分布',
   'コインを1回投げて、表が出たら1、裏が出たら0と決めておく。このように「偶然で決まる結果に数字を対応させたもの」を何と呼ぶ？',
   NULL::text,
   '["確率変数", "確率そのもの", "代表値", "確率分布"]',
   0, '[0]', 'single',
   '{"asked": "「結果」そのものに数字の名札をつける、という考え方の名前。", "point": "偶然で決まる結果に数字を対応させたものが確率変数。コインの表裏を1と0に変換するのがその一例。", "kid": "表・裏という言葉のままでは計算がしにくい。そこで「表なら1、裏なら0」のように、結果1つ1つに数字の名札をつける。この「数字に変換されたもの」を確率変数と呼ぶ。", "eg": "サッカーの勝ち・引き分け・負けに、勝ち点3・1・0を割り振るのと同じ発想。試合結果という出来事に、計算できる数字を対応させている。", "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><circle cx=\"70\" cy=\"46\" r=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"70\" y=\"42\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\" font-weight=\"600\">表</text><text x=\"70\" y=\"60\" fill=\"#8892a4\" font-size=\"7\" text-anchor=\"middle\">OMOTE</text><circle cx=\"70\" cy=\"112\" r=\"26\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"70\" y=\"108\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\" font-weight=\"600\">裏</text><text x=\"70\" y=\"126\" fill=\"#8892a4\" font-size=\"7\" text-anchor=\"middle\">URA</text><line x1=\"100\" y1=\"46\" x2=\"185\" y2=\"46\" stroke=\"#2a2f3f\"/><line x1=\"100\" y1=\"112\" x2=\"185\" y2=\"112\" stroke=\"#2a2f3f\"/><polygon points=\"185,46 176,41 176,51\" fill=\"#2a2f3f\"/><polygon points=\"185,112 176,107 176,117\" fill=\"#2a2f3f\"/><rect x=\"196\" y=\"30\" width=\"60\" height=\"32\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"226\" y=\"51\" fill=\"#60a5fa\" font-size=\"16\" text-anchor=\"middle\" font-weight=\"600\">1</text><rect x=\"196\" y=\"96\" width=\"60\" height=\"32\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"226\" y=\"117\" fill=\"#e8eaf0\" font-size=\"16\" text-anchor=\"middle\" font-weight=\"600\">0</text><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">結果に「数字の名札」をつける</text></svg>", "terms": [["確率変数", "偶然の結果に対応させた数字。値そのものは試行するまで分からない"], ["試行", "コインを投げる・サイコロを振るなど、結果が偶然で決まる1回の行為"]], "think": "「表」「裏」という言葉のままでは、平均を計算したり足し合わせたりできない。だから結果ごとに数字を割り当てる。表=1、裏=0と決めておけば、たとえば「10回投げて表が出た回数の平均」のような計算が、ふつうの数字の足し算・平均の計算としてできるようになる。確率変数は、偶然の出来事を計算の土俵に乗せるための橋渡し役。", "vs": "確率は「その結果が起きる割合（0〜1の数）」、確率変数は「結果そのものに対応する数字（この例では0か1）」。似た言葉だが、確率変数のほうは値そのもの、確率のほうはその値が出る割合を指す。", "why_asked": "期待値や分布はすべて「確率変数がどんな値をとり、それぞれどれくらいの確率で出るか」の話。確率変数という土台を作らないと、この先の期待値・分布の計算がすべて言葉遊びで終わってしまう。", "usecase": "サイコロの出目、コインの表裏、くじの当たり外れ、テストの正解不正解。「偶然で決まる結果を数字として扱いたい」場面すべての出発点。", "opt": ["正解。偶然で決まる結果に数字を対応させたものが確率変数。", "確率は、その数字（結果）がどれくらいの割合で出るかを表す0〜1の数で、結果に対応させた数字そのものとは別物。", "代表値は平均値や中央値のように、集めたデータ全体を1つの数字で代表させたもので、1回の結果に対応させる数字とは意味が違う。", "分布は、確率変数がとりうる値ごとに、どれだけ出やすいかを一覧にしたもので、1回の結果に数字を対応させる作業そのものではない。"]}'),

  ('stats2-q03', '確率と分布',
   '1回200円のくじがある。1000円が当たる確率は1/10、100円が当たる確率は3/10、残りは外れ（0円）。このくじを1回引くと平均いくら戻ってくる計算になる？',
   NULL::text,
   '["130円", "550円", "300円", "1000円"]',
   0, '[0]', 'single',
   '{"asked": "「平均するといくら戻るか」を計算する期待値の考え方。", "point": "期待値は「賞金×その確率」を全部たした値。1000×1/10 + 100×3/10 + 0×6/10 = 130円。", "kid": "期待値は「このくじを何回も引き続けたら、1回あたり平均いくら戻ってくるか」を先に計算しておいた数字。実際に1回引いたら1000円か100円か0円のどれかしか出ないが、たくさん引けば平均は130円に近づいていく。", "eg": "的当てゲームで、1000円の的に当たる確率は10回に1回、100円の的は10回に3回、残りは外れ。何度もやり続けたときの「1回あたりのならし賞金」を先に計算しておくのが期待値。", "viz": "<svg viewBox=\"0 0 340 144\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"30\" y=\"30\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"start\" font-weight=\"600\">1000円</text><text x=\"140\" y=\"30\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">×</text><text x=\"160\" y=\"30\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"start\">1/10</text><text x=\"232\" y=\"30\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">=</text><text x=\"252\" y=\"30\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"start\" font-weight=\"600\">100円</text><text x=\"30\" y=\"58\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"start\" font-weight=\"600\">100円</text><text x=\"140\" y=\"58\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">×</text><text x=\"160\" y=\"58\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"start\">3/10</text><text x=\"232\" y=\"58\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">=</text><text x=\"252\" y=\"58\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"start\" font-weight=\"600\">30円</text><text x=\"30\" y=\"86\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"start\" font-weight=\"600\">0円</text><text x=\"140\" y=\"86\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">×</text><text x=\"160\" y=\"86\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"start\">6/10</text><text x=\"232\" y=\"86\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">=</text><text x=\"252\" y=\"86\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"start\" font-weight=\"600\">0円</text><line x1=\"20\" y1=\"98\" x2=\"320\" y2=\"98\" stroke=\"#2a2f3f\"/><text x=\"30\" y=\"114\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"start\">合計</text><text x=\"252\" y=\"114\" fill=\"#3b82f6\" font-size=\"13\" text-anchor=\"start\" font-weight=\"600\">130円</text><text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1回あたり平均130円がもどってくる計算</text></svg>", "terms": [["期待値", "確率変数がとる値と、その値が出る確率をかけて全部たした値。平均するとこうなる、という数"], ["賞金（値）", "確率変数がとりうる具体的な数字。ここでは1000円・100円・0円"]], "think": "1000円が出る確率は1/10なので、10回に1回のペースで1000円が出るとみなせる。1回あたりに直すと1000×1/10＝100円ぶんの価値になる。同じように100円が出る割合は100×3/10＝30円ぶん、外れは0×6/10＝0円ぶん。この「1回あたりに直した価値」を全部たすと130円。実際の1回の結果は必ず1000円・100円・0円のどれかで130円にはならないが、これは「たくさん繰り返したときの1回あたりの平均」を先回りして計算した数字。", "vs": "200円という参加費は期待値の計算には出てこない。期待値130円は「戻ってくる賞金の平均」であって、「得か損か」を見るには参加費200円と比べて初めて分かる（130円<200円なので、このくじは平均すると損）。", "why_asked": "保険もギャンブルも投資も、「平均するとどうなるか」を先に計算できないと損得の判断ができない。期待値は、まだ起きていない先の結果を、今の時点で1つの数字に要約する道具として生まれた。", "usecase": "宝くじや保険の損得計算、投資判断（期待リターン）、ゲームのガチャの実質価値の見積もり。「割に合うか」を数字で判断したいときに使う。", "opt": ["正解。1000×1/10 + 100×3/10 + 0×6/10 を計算すると130円になる。", "550円は1000円と100円の単純な平均（(1000+100)÷2）で、確率の重みを無視した計算になっている。", "300円は100円×3という計算で、確率3/10を「3回当たる」と取り違えた値になっている。", "1000円は最高賞金そのもので、それが出る確率の低さ（10回に1回）を反映していない。"]}'),

  ('stats2-q04', '確率と分布',
   'サイコロを2個同時に振って、出た目の合計を記録する。これを何度も繰り返したとき、一番出やすい合計はどれ？',
   NULL::text,
   '["7", "2", "12", "6と8は同じくらい出やすい"]',
   0, '[0]', 'single',
   '{"asked": "「どの値がどれだけ出やすいか」という一覧＝確率分布の読み方。", "point": "組み合わせの数が一番多いのが7（1+6, 2+5, 3+4…の6通り）。だから7が最頻の合計になる。", "kid": "サイコロ2個の合計は2から12まである。でも全部が同じ出やすさではない。2になる組み合わせは「1と1」の1通りしかないが、7になる組み合わせは「1と6」「2と5」「3と4」「4と3」「5と2」「6と1」の6通りある。組み合わせが多いほど出やすい。", "eg": "くじ引きの箱に、7が出る組み合わせのカードが6枚、2が出る組み合わせのカードが1枚入っているようなもの。カードの枚数が多いほど引かれやすい。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"24\" y=\"100\" width=\"22\" height=\"12\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"35\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2</text><rect x=\"51\" y=\"88\" width=\"22\" height=\"24\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"62\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">3</text><rect x=\"78\" y=\"76\" width=\"22\" height=\"36\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"89\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">4</text><rect x=\"105\" y=\"64\" width=\"22\" height=\"48\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"116\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">5</text><rect x=\"132\" y=\"52\" width=\"22\" height=\"60\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"143\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">6</text><rect x=\"159\" y=\"40\" width=\"22\" height=\"72\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"170\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">7</text><rect x=\"186\" y=\"52\" width=\"22\" height=\"60\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"197\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">8</text><rect x=\"213\" y=\"64\" width=\"22\" height=\"48\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"224\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">9</text><rect x=\"240\" y=\"76\" width=\"22\" height=\"36\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"251\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">10</text><rect x=\"267\" y=\"88\" width=\"22\" height=\"24\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"278\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">11</text><rect x=\"294\" y=\"100\" width=\"22\" height=\"12\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"305\" y=\"126\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">12</text><line x1=\"20\" y1=\"112\" x2=\"320\" y2=\"112\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">2個のサイコロの目の和は7が一番出やすい</text></svg>", "terms": [["確率分布", "確率変数がとりうる値ごとに、どれだけ出やすいか（確率）をまとめた一覧"], ["組み合わせ", "同じ合計になる出方の数のこと"]], "think": "サイコロ2個の出方は全部で6×6＝36通りある。合計が2になるのは(1,1)の1通りだけなので確率は1/36。合計が7になるのは(1,6)(2,5)(3,4)(4,3)(5,2)(6,1)の6通りあるので確率は6/36。同じ36通りの中でも、合計ごとに何通り作れるかが違うので、出やすさに差が出る。この「値ごとの出やすさの一覧」が確率分布そのもの。", "vs": "「サイコロ1個の目」はどの目も1/6で完全に均等な分布だったが、「サイコロ2個の和」は真ん中の値ほど作れる組み合わせが多いので、山型の分布になる。同じサイコロでも、何を確率変数にするかで分布の形は変わる。", "why_asked": "1つの値だけを見ても全体は見えない。「どの値がどれだけ出やすいか」を一覧にして初めて、平均や分散、正規分布や二項分布といったこの先の話が組み立てられる。", "usecase": "ボードゲーム（すごろく・モノポリー）でのマス目設計、品質検査での不良個数の見積もり、保険会社の事故件数の見積もり。", "opt": ["正解。合計7を作る組み合わせが1〜6の目の中で一番多い（6通り）ので、7が一番出やすい。", "2は「1と1」の1通りでしか作れず、36通り中もっとも出にくい合計の1つ。", "12も「6と6」の1通りでしか作れず、2と同じくらい出にくい合計。", "6は5通り、8も5通りで確かに同じ出やすさだが、7の6通りにはわずかに及ばない。"]}'),

  ('stats2-q05', '確率と分布',
   'コインを10回投げて、表が出た回数を数える実験を何度も繰り返す。この「10回中の表の回数」の分布のように、「同じ実験をn回繰り返して、ある結果が何回出るか」を表す分布を何と呼ぶ？',
   NULL::text,
   '["二項分布", "正規分布", "確率変数", "期待値"]',
   0, '[0]', 'single',
   '{"asked": "「n回のうち何回当たったか」を表す分布の名前。", "point": "「当たり／外れの2択」を「n回」繰り返したときの当たり回数の分布が二項分布。コイン投げの表の回数はその代表例。", "kid": "コインを10回投げると、表が0回の人もいれば10回の人もいる。一番多いのは5回あたりで、0回や10回はめったに起きない。「表・裏という2択の実験をn回繰り返したとき、当たり（表）が何回出るか」の出やすさの一覧が二項分布。", "eg": "10本のくじを引いて「当たり」が何本出たかを数えるようなもの。当たりの出方は毎回2択（当たりか外れか）で、それをn回繰り返した結果の分布。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"20\" y=\"112.0\" width=\"23\" height=\"0.0\" fill=\"#2a2f3f\"/><text x=\"31\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">0</text><rect x=\"48\" y=\"109.4\" width=\"23\" height=\"2.6\" fill=\"#2a2f3f\"/><rect x=\"76\" y=\"101.6\" width=\"23\" height=\"10.4\" fill=\"#2a2f3f\"/><text x=\"87\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">2</text><rect x=\"104\" y=\"80.8\" width=\"23\" height=\"31.200000000000003\" fill=\"#2a2f3f\"/><rect x=\"132\" y=\"57.4\" width=\"23\" height=\"54.6\" fill=\"#2a2f3f\"/><text x=\"143\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">4</text><rect x=\"160\" y=\"47.0\" width=\"23\" height=\"65.0\" fill=\"#3b82f6\"/><rect x=\"188\" y=\"57.4\" width=\"23\" height=\"54.6\" fill=\"#2a2f3f\"/><text x=\"199\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">6</text><rect x=\"216\" y=\"80.8\" width=\"23\" height=\"31.200000000000003\" fill=\"#2a2f3f\"/><rect x=\"244\" y=\"101.6\" width=\"23\" height=\"10.4\" fill=\"#2a2f3f\"/><text x=\"255\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">8</text><rect x=\"272\" y=\"109.4\" width=\"23\" height=\"2.6\" fill=\"#2a2f3f\"/><rect x=\"300\" y=\"112.0\" width=\"23\" height=\"0.0\" fill=\"#2a2f3f\"/><text x=\"311\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">10</text><line x1=\"18\" y1=\"112\" x2=\"318\" y2=\"112\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">コインを10回投げて表が出た回数</text><text x=\"160\" y=\"30\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">5回が一番多い</text></svg>", "terms": [["二項分布", "当たり／外れの2択の試行をn回繰り返したときの、当たり回数の分布"], ["試行回数（n）", "同じ実験を繰り返す回数。コイン投げなら「何回投げるか」"]], "think": "コイン投げ1回だけなら結果は表か裏の2つしかない。でも10回繰り返すと、表の回数は0回から10回までの11通りがありえて、しかもその出やすさには差がある。表5回になる組み合わせの数は、表0回や表10回になる組み合わせの数よりずっと多い（さっきのサイコロ2個の和と同じ理屈）。だから「表5回あたり」が一番出やすい山型の分布ができる。これが二項分布の正体。", "vs": "正規分布は連続的な値（身長やテストの点）が作る釣り鐘型の分布で、二項分布は「回数」という飛び飛びの値が作る分布。ただし試行回数nが大きくなると、二項分布の形は正規分布にどんどん近づいていく。", "why_asked": "「n回試したうち何回成功するか」は、品質検査の不良品率、選挙の当落予想、薬の効果検証など、実務でとても多いパターン。この形を名前つきで扱えるようにしたのが二項分布。", "usecase": "工場で1000個の製品を検査して不良品が何個混ざるかの見積もり、世論調査でn人に聞いたときの賛成人数の見積もり、A/Bテストでのクリック数の見積もり。", "opt": ["正解。当たり／外れの2択の試行をn回繰り返したときの当たり回数の分布が二項分布。", "正規分布は連続的な値が作る釣り鐘型の分布で、回数を数える二項分布とは土台が違う（試行回数が増えると近づいてはいく）。", "確率変数は結果に対応させた数字そのもののことで、その数字がどう分布するかという一覧そのものではない。", "期待値は分布の平均にあたる1つの数字であって、値ごとの出やすさをすべて記録した一覧ではない。"]}'),

  ('stats2-q06', '確率と分布',
   '多くの人の身長や、定規で同じ長さを測ったときの誤差は、平均の近くにデータが集まり、離れるほど少なくなる左右対称の山型になりやすい。この代表的な形の分布を何と呼ぶ？',
   NULL::text,
   '["正規分布", "二項分布", "確率分布", "確率変数"]',
   0, '[0]', 'single',
   '{"asked": "自然界や測定でよく現れる、左右対称の釣り鐘型の分布の名前。", "point": "平均のまわりに一番データが集まり、離れるほど少なくなる左右対称の釣り鐘型が正規分布。", "kid": "正規分布は、真ん中（平均）が一番高くて、そこから左右になだらかに低くなっていく釣り鐘のような形の分布。身長・体重・測定の誤差など、自然に生まれる量の多くがこの形になる。", "eg": "クラス全員を身長順に並べて記念写真を撮ると、真ん中あたりの背の高さの人がいちばん多く、極端に低い人・高い人はだんだん少なくなる。この人数の集まり方を絵にすると釣り鐘の形になる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M20 118 C 100 118, 115 22, 170 22 C 225 22, 240 118, 320 118\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><line x1=\"20\" y1=\"118\" x2=\"320\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"118\" x2=\"170\" y2=\"22\" stroke=\"#2a2f3f\" stroke-dasharray=\"4 3\"/><text x=\"170\" y=\"134\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">平均（真ん中に集まる）</text><text x=\"60\" y=\"100\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">少ない</text><text x=\"280\" y=\"100\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">少ない</text><text x=\"170\" y=\"14\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">身長や測定誤差はこの釣り鐘型になりやすい</text></svg>", "terms": [["正規分布", "平均を中心に左右対称の釣り鐘型になる、自然界でよく現れる分布"], ["釣り鐘型", "正規分布の形のたとえ。真ん中が高く、両端がなだらかに低い"]], "think": "身長は「たくさんの小さな要因（遺伝・栄養・生活習慣など）が積み重なって決まる」量。こういう「いろんな要因が足し合わさって決まる量」は、極端に高い・低いになる要因の組み合わせは少なく、平均あたりに落ち着く組み合わせが圧倒的に多い。だから真ん中に人が集まり、両端に行くほど少なくなる左右対称の山ができる。この「たくさんの要因の積み重ねが釣り鐘を作る」仕組みは、あとで習う中心極限定理という考え方の入り口でもある。", "vs": "二項分布は「回数」という飛び飛びの値の分布だが、正規分布は身長のように「連続的に測れる値」の分布。ただし二項分布も試行回数が多くなると正規分布に似た形に近づく。", "why_asked": "偏差値・68-95ルール・標準化（z値）など、この先に習う道具はほとんどが「分布が正規分布に近い」ことを前提にしている。土台となる形を先に押さえておかないと、あとの単元が全部宙に浮く。", "usecase": "身長・体重の成長曲線、測定誤差の見積もり、テストの点数分布のモデル化、品質管理での製品寸法のばらつき管理。", "opt": ["正解。平均を中心に左右対称の釣り鐘型になる分布が正規分布。身長や測定誤差の代表的な形。", "二項分布はコイン投げのように「n回のうち何回当たったか」という回数の分布で、連続的な測定値の分布とは前提が違う。", "確率分布は「値ごとの出やすさの一覧」全般を指す広い言葉で、正規分布はその中の代表的な1つの形にすぎない。", "確率変数は結果に対応させた数字そのもののことで、分布の形（山のでき方）を表す言葉ではない。"]}'),

  ('stats2-q07', '確率と分布',
   'テストの点数が正規分布に近い形をしていて、平均60点・標準偏差10点だとする。「平均±1個ぶん（50点〜70点）」の範囲には、全体のおよそ何%の人が入る？',
   NULL::text,
   '["約68%", "約95%", "約50%", "ほぼ100%"]',
   0, '[0]', 'single',
   '{"asked": "正規分布での「平均からのはば」と「入る割合」の対応関係。", "point": "正規分布では、平均±標準偏差1個ぶんに約68%、平均±2個ぶんに約95%が入る。これが68-95ルール。", "kid": "正規分布の山には、決まった約束がある。平均から標準偏差1個ぶんの範囲（この例では50点〜70点）に、全体のおよそ68%の人が集まっている。標準偏差2個ぶんの範囲（40点〜80点）まで広げると、およそ95%まで増える。", "eg": "的の中心（平均）に近いほど矢が集まる弓道の的をイメージする。中心から一定の輪の中に矢の約68%、もう一回り広い輪までにはおよそ95%が刺さっている、という決まった割合がある。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M20 74 C 90 74, 105 20, 170 20 C 235 20, 250 74, 320 74\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><line x1=\"20\" y1=\"74\" x2=\"320\" y2=\"74\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><line x1=\"123\" y1=\"16\" x2=\"123\" y2=\"74\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"123\" y=\"12\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">-1σ</text><line x1=\"170\" y1=\"16\" x2=\"170\" y2=\"74\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"170\" y=\"12\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">平均</text><line x1=\"217\" y1=\"16\" x2=\"217\" y2=\"74\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"217\" y=\"12\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">+1σ</text><rect x=\"123\" y=\"90\" width=\"94\" height=\"12\" rx=\"2\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"170\" y=\"106\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">±1σ に約68%</text><rect x=\"80\" y=\"116\" width=\"180\" height=\"12\" rx=\"2\" fill=\"#3b82f6\" opacity=\"0.28\"/><text x=\"170\" y=\"132\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">±2σ に約95%</text></svg>", "terms": [["68-95ルール", "正規分布で平均±1σに約68%、±2σに約95%が入るという経験則"], ["標準偏差（σ）", "ばらつきの大きさを表す数字。ここでは10点"]], "think": "正規分布は形がいつも同じ「相似形」になっている。だから平均から標準偏差何個ぶん離れているかさえ分かれば、その範囲に何%の人が入るかは、テストの種類が違っても常に同じ割合になる。実際に確かめると、平均±1個ぶんでおよそ68%、±2個ぶんでおよそ95%、±3個ぶんではほぼ100%(99.7%)という決まった数字になることが分かっている。50点〜70点はちょうど平均±1個ぶんなので、約68%が答え。", "vs": "「約95%」は平均±2個ぶん（40点〜80点）の割合で、今回問われている±1個ぶん（50点〜70点）とは範囲の広さが違う。範囲を2倍に広げても、入る人の割合は2倍にはならず、68%から95%までしか増えない点に注意。", "why_asked": "偏差値やテストの合格ライン、品質管理の合格範囲など、「平均からどれくらい離れていたら普通で、どれくらいで珍しいか」を判断する場面で、この68-95という具体的な割合が土台として使われる。", "usecase": "模試の成績表で「あなたの順位はだいたい上位◯%」を出す計算、工場の検査で「平均±3σを外れたら不良品」とする管理基準、健康診断の基準値の設定。", "opt": ["正解。正規分布では平均±1個ぶんの範囲に、全体のおよそ68%が入る。", "約95%が入るのは平均±2個ぶん（この例では40点〜80点）の範囲で、今回の50点〜70点よりも広い範囲の割合。", "約50%は中央値ちょうどで分けたときの片側の割合で、平均±1個ぶんの範囲の割合とは別の数字。", "ほぼ100%になるのは平均±3個ぶん（この例では30点〜90点）まで範囲を広げたとき。"]}'),

  ('stats2-q08', '確率と分布',
   '国語のテスト（平均60点・標準偏差10点）で80点、数学のテスト（平均50点・標準偏差20点）でも80点を取った。「平均からどれだけ離れているか」を、どちらのテストでも比べられる共通のものさしに直すために使う値を何と呼ぶ？',
   NULL::text,
   '["z値", "確率変数", "期待値", "確率分布"]',
   0, '[0]', 'single',
   '{"asked": "平均も標準偏差も違うテスト同士を比べるための、共通のものさしの名前。", "point": "z値＝（点数−平均）÷標準偏差。平均を0、標準偏差1個ぶんを1にそろえ直した共通のものさし。", "kid": "国語も数学も同じ80点だが、平均もばらつき（標準偏差）も違うので、80点の「すごさ」は同じではない。そこでどちらのテストも「平均を0、標準偏差1個ぶんを1」という共通のものさしに変換する。この変換した値がz値。", "eg": "国によって通貨がバラバラだと値段を比べられないので、いったんすべて円に両替してから比べる。z値は、どんなテストの点数でも両替できる「共通通貨」にあたる。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"90\" y=\"20\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">元のものさし（点数）</text><line x1=\"20\" y1=\"40\" x2=\"160\" y2=\"40\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"40\" x2=\"30\" y2=\"46\" stroke=\"#2a2f3f\"/><text x=\"30\" y=\"58\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">40</text><line x1=\"90\" y1=\"40\" x2=\"90\" y2=\"46\" stroke=\"#2a2f3f\"/><text x=\"90\" y=\"58\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">60</text><line x1=\"150\" y1=\"40\" x2=\"150\" y2=\"46\" stroke=\"#2a2f3f\"/><text x=\"150\" y=\"58\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">80</text><circle cx=\"150\" cy=\"40\" r=\"4.5\" fill=\"#3b82f6\"/><line x1=\"90\" y1=\"76\" x2=\"180\" y2=\"100\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"180,100 171,96 172,105\" fill=\"#60a5fa\"/><text x=\"135\" y=\"84\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">両替する</text><text x=\"250\" y=\"108\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">共通のものさし（z値）</text><line x1=\"180\" y1=\"126\" x2=\"320\" y2=\"126\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"202\" y1=\"126\" x2=\"202\" y2=\"132\" stroke=\"#2a2f3f\"/><text x=\"202\" y=\"144\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">-1</text><line x1=\"250\" y1=\"126\" x2=\"250\" y2=\"132\" stroke=\"#2a2f3f\"/><text x=\"250\" y=\"144\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">0</text><line x1=\"306\" y1=\"126\" x2=\"306\" y2=\"132\" stroke=\"#2a2f3f\"/><text x=\"306\" y=\"144\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">+2</text><circle cx=\"306\" cy=\"126\" r=\"4.5\" fill=\"#3b82f6\"/><text x=\"250\" y=\"100\" fill=\"#3b82f6\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">80点 → z = +2</text></svg>", "terms": [["z値（標準化）", "（値−平均）÷標準偏差で計算する、平均0・標準偏差1にそろえ直した値"], ["標準化", "平均や単位がバラバラなデータを、共通のものさしに変換する作業"]], "think": "国語は80点で、平均60点との差は20点。この20点を標準偏差10点で割ると、z値は+2、つまり「平均より標準偏差2個ぶん上」。数学は80点で、平均50点との差は30点。これを標準偏差20点で割るとz値は+1.5、「平均より標準偏差1.5個ぶん上」。同じ80点でも、z値に直すと国語のほうが平均から遠く離れた、相対的にすごい点数だったと分かる。差の大きさをそのまま比べず、標準偏差で割って「はば何個ぶんか」に直すのがz値のキモ。", "vs": "偏差値はz値を「10倍して50を足した」もの（z値×10＋50）。z値は平均0・幅1のものさし、偏差値は平均50・幅10のものさしという違いはあるが、どちらも同じ標準化という考え方の別の表し方。", "why_asked": "テストのように、平均も難易度も違う集団同士を公平に比べたい場面は多い。z値という共通のものさしがないと、点数の大小だけで「すごさ」を誤って比べてしまう。偏差値の計算の裏側でも、このz値が使われている。", "usecase": "偏差値の計算、模試や検定の異なる回次どうしの成績比較、複数の指標（身長・体重など単位が違う項目）を1つのスコアにまとめるときの前処理。", "opt": ["正解。（点数−平均）÷標準偏差で計算し、平均0・標準偏差1にそろえ直した値がz値。", "確率変数は結果に対応させた数字そのもののことで、平均やばらつきの違いを補正して比べるための値ではない。", "期待値は「平均するといくらになるか」を表す1つの数字で、個々の点数を共通のものさしに変換する計算ではない。", "確率分布は値ごとの出やすさの一覧のことで、2つのテストの点数を比べるための変換方法ではない。"]}'),

  ('stats2-q09', '確率と分布',
   'コインを10回だけ投げると、表が7回や8回出ることも珍しくない。ところが1万回投げると、表が出た割合はほぼ1/2にぴたりと近づく。この「回数を増やすほど割合が理論値に落ち着く」という性質を何と呼ぶ？',
   NULL::text,
   '["大数の法則", "中心極限定理", "68-95ルール", "確率密度"]',
   0, '[0]', 'single',
   '{"asked": "「試す回数を増やすほど結果が理論値に近づく」という性質の名前。", "point": "回数が少ないと割合はブレやすいが、回数を増やすほど理論上の確率（コインなら1/2）に近づいていく。これが大数の法則。", "kid": "コインを10回しか投げないと、表が7回や3回になることも普通に起きる。でも100回、1000回、1万回と回数を増やしていくと、表が出た割合はだんだん1/2にそろっていく。「たくさん繰り返すほど、実際の割合が理論上の確率に近づく」という性質を大数の法則と呼ぶ。", "eg": "サイコロを6回振っただけでは1の目が1回も出ないことも普通にある。でも6万回振れば、1の目が出た回数はだいたい1万回（6分の1）に近い数になる。回数を増やすほど「ならされて」いく。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"30\" y1=\"118\" x2=\"320\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"20\" x2=\"30\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"68\" x2=\"320\" y2=\"68\" stroke=\"#c9a04a\" stroke-dasharray=\"4 3\"/><text x=\"316\" y=\"62\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"end\">1/2</text><path d=\"M30 30 L55 98 L80 40 L110 88 L145 54 L180 78 L215 62 L250 72 L285 65 L316 69\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><text x=\"170\" y=\"14\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">投げる回数を増やすほど</text><text x=\"170\" y=\"28\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">表の割合は1/2に落ち着く</text><text x=\"30\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">回数 少ない</text><text x=\"320\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">回数 多い</text></svg>", "terms": [["大数の法則", "試行回数を増やすほど、結果の割合が理論上の確率に近づいていくという性質"], ["理論上の確率", "計算上決まっている出やすさ。コインの表なら1/2"]], "think": "コイン投げ10回では、たまたま表が続く・裏が続くという「偏り」の影響が全体に対して大きく残ってしまう。ところが1万回投げると、その偏りは全体の回数に比べてごく小さな割合になり、目立たなくなる。回数を増やすほど「たまたまの影響」が薄まっていくので、表が出た割合は理論上の1/2にどんどん近づいていく。これが大数の法則の仕組み。", "vs": "中心極限定理は「平均という数字の分布がベル型に近づく」という別の性質で、大数の法則は「割合や平均そのものが1つの値に近づいていく」という性質。似た場面(回数を増やす)で出てくるが、主張している中身が違う。", "why_asked": "「たった数回の結果」と「大量に繰り返した結果」は全く別物だと分かっていないと、少ない試行の結果を理論値のように扱って判断を誤る。保険会社やカジノがビジネスとして成り立つのは、まさにこの法則のおかげ。", "usecase": "保険会社が「大勢の契約者を集めれば事故率がほぼ一定の割合に落ち着く」と見込んで保険料を決めること、世論調査で回答者数を増やすほど実際の支持率に近づくこと、品質検査でのサンプル数の考え方。", "opt": ["正解。試行回数を増やすほど、実際の割合が理論上の確率に近づいていくという性質が大数の法則。", "中心極限定理は、元の分布の形にかかわらず「平均」の分布がベル型に近づいていくという別の性質。", "68-95ルールは正規分布において平均からのはばと入る割合の対応を示す経験則で、回数を増やす話とは別の内容。", "確率密度は、連続的な値の分布で「面積が確率になる」という考え方で、回数と割合の収束とは異なるテーマ。"]}'),

  ('stats2-q10', '確率と分布',
   'サイコロの目やコインの表裏のようにきれいな形ではない、いびつな分布を持つ集団からでも、たくさんサンプルを取って「その平均」を何度も計算し、その平均たちを集めて分布にすると、どんな形に近づいていく？',
   NULL::text,
   '["正規分布に近い釣り鐘型", "元の分布と同じいびつな形", "真ん中がへこんだ形", "常に一直線（平ら）"]',
   0, '[0]', 'single',
   '{"asked": "「平均という数字」を何度も計算して集めると、どんな分布になるか。", "point": "元の分布がどんな形でも、1回に平均を取る標本の大きさ（サンプルサイズ n）が十分大きければ、その平均を集めた分布は正規分布に近づく。これが中心極限定理。", "kid": "たとえば、ある品物の重さの分布がすごく左右非対称ないびつな形をしていたとする。そこから10個ずつ取り出して平均を計算する、という作業を何度も繰り返す。その「10個ずつの平均」を集めて分布にすると、元の重さの分布がいびつでも、平均の分布はきれいな釣り鐘型（正規分布）に近づいていく。", "eg": "サイコロの目1〜6は均等な四角い分布（山型ではない）。でもサイコロを何個も同時に振って、その合計や平均を何度も計算して集めると、山型（正規分布に近い形）になっていく。さっき見た「サイコロ2個の和」が7を頂点に山型になったのも、この仕組みの小さな例。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"24\" y=\"103.8\" width=\"10\" height=\"4.199999999999999\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"36\" y=\"101.0\" width=\"10\" height=\"7.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"48\" y=\"96.8\" width=\"10\" height=\"11.2\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"60\" y=\"89.8\" width=\"10\" height=\"18.2\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"72\" y=\"80.0\" width=\"10\" height=\"28.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"84\" y=\"66.0\" width=\"10\" height=\"42.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"96\" y=\"46.400000000000006\" width=\"10\" height=\"61.599999999999994\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"108\" y=\"24.0\" width=\"10\" height=\"84.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><line x1=\"20\" y1=\"108\" x2=\"140\" y2=\"108\" stroke=\"#2a2f3f\"/><text x=\"80\" y=\"132\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">元はいびつな形</text><line x1=\"152\" y1=\"70\" x2=\"200\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"200,70 191,65 191,75\" fill=\"#8892a4\"/><text x=\"176\" y=\"60\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">平均を</text><text x=\"176\" y=\"92\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">何度もとる</text><path d=\"M212 108 C 250 108, 258 30, 285 30 C 312 30, 320 108, 320 108\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><line x1=\"212\" y1=\"108\" x2=\"320\" y2=\"108\" stroke=\"#2a2f3f\"/><text x=\"266\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">「平均」の分布はベル型</text></svg>", "terms": [["中心極限定理", "元の分布がどんな形でも、標本の大きさnが十分大きければ、標本の平均を集めた分布は正規分布に近づくという定理"], ["標本平均", "母集団の一部（標本）から計算した平均のこと"]], "think": "1個の重さは軽いことも重いことも極端に起こりうるいびつな分布かもしれない。でも「10個の平均」を考えると、たまたま全部軽い10個が集まる確率や、全部重い10個が集まる確率はとても低く、多くの場合は軽いものと重いものが混ざって平均は真ん中あたりに落ち着く。この「極端に偏った組み合わせほど起きにくく、真ん中あたりの組み合わせが圧倒的に多い」という理屈は、正規分布が生まれる仕組みそのもので、サイコロ2個の和が7に集中したのと同じ理屈。だから、元の形がいびつでも「平均」を何度も取って集めると、山は正規分布に近づく。", "vs": "大数の法則は「回数を増やすと1つの割合や平均が理論値そのものに近づく」という話。中心極限定理は「1回に平均を取る標本の大きさ n が十分大きければ、その平均の分布が正規分布に近づく」という話で、注目している対象が違う。何度も平均を計算して分布の形をヒストグラムで確かめているのは、あくまで形を目で見えるようにするためのシミュレーションであり、分布の形を正規に近づけているのは標本を取り直した回数ではなく、1回あたりのnの大きさそのもの。", "why_asked": "世の中のデータは正規分布とは限らない。それでも「平均」を扱うときには正規分布の道具（68-95ルールなど）が使えることが多いのは、この定理のおかげ。推測統計（標本から母集団を推し量る）の土台になる、統計学でもっとも重要な定理の1つ。", "usecase": "選挙の出口調査（一部の投票者の平均的な支持傾向から全体を推定）、工場の抜き取り検査（一部の平均から全体の品質を推定）、アンケート調査の平均値の信頼区間の計算。", "opt": ["正解。元の分布がいびつでも、標本の大きさnが十分大きければ、その平均を集めた分布は正規分布に近づく。", "元の分布と同じいびつな形のままなら、平均という計算をわざわざする意味が薄れてしまう。実際には整った形に近づいていく。", "真ん中がへこんだ形になるのは、平均を集めた分布の一般的な性質ではなく、むしろ逆に真ん中に集まりやすくなる。", "常に一直線（平ら）になるのは、すべての平均が同じ出やすさという意味になってしまい、実際に起きる集まり方とは異なる。"]}'),

  ('stats2-q11', '確率と分布',
   '身長のように連続的に測れる値の分布では、「ちょうど165.0000…cm」という1点だけの確率を考えると0になってしまう。その代わりに「160cmから170cmのあいだ」のような範囲の確率を表すとき、グラフの何を見ればいい？',
   NULL::text,
   '["曲線の下の面積", "曲線の一番高い場所の高さ", "曲線と横軸が交わる点の数", "曲線の傾きの急さ"]',
   0, '[0]', 'single',
   '{"asked": "連続的な値の分布で、範囲の確率をグラフから読み取る方法。", "point": "連続的な値では、範囲の確率は「その範囲にあたる、曲線の下の面積」で表される。1点だけの確率は面積0なので常に0になる。", "kid": "身長は165.0cmぴったりの人もいれば165.001cmの人もいて、区切りなく無限に細かく分けられる値。だから「ちょうど165.0000…cm」という1点にしぼると、そこにあたる人の割合は限りなく0に近い。その代わり「160cm〜170cmの範囲に入る人の割合」なら、ちゃんと0より大きい数字として求められる。この範囲の確率が、グラフの曲線の下の面積として表される。", "eg": "ものさしで長さを測るとき、「ちょうど10.0cm」を寸分の狂いもなく測ることは事実上できない。でも「9.9cmから10.1cmのあいだ」なら、はっきり測れる。1点はつかめないが、幅（範囲）ならつかめる、という感覚に近い。", "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><path d=\"M20 108 C 90 108, 105 24, 170 24 C 235 24, 250 108, 320 108\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><line x1=\"20\" y1=\"108\" x2=\"320\" y2=\"108\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><path d=\"M140 108 L140 62 L200 50 L200 108 Z\" fill=\"#3b82f6\" opacity=\"0.35\"/><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"108\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"140\" y=\"122\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">160cm</text><line x1=\"200\" y1=\"20\" x2=\"200\" y2=\"108\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/><text x=\"200\" y=\"122\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">170cm</text><text x=\"170\" y=\"84\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">この面積が確率</text><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">ピンポイント「ちょうど165.0cm」の確率は0</text></svg>", "terms": [["確率密度", "連続的な値の分布での、曲線の高さのこと。それ自体は確率ではなく、面積にして初めて確率になる"], ["連続的な値", "身長や体重、時間のように、区切りなくどこまでも細かく測れる値"]], "think": "サイコロの目のような飛び飛びの値なら「1の目が出る確率」のように1点の確率をそのまま言える。でも身長のような連続的な値は、測る精度をどこまでも上げられるので、区切りとなる1点は無数にあり、1点ちょうどにあたる確率はどこまでも0に近づいてしまう。そこで「1点」ではなく「範囲」で考える。曲線の高さ（確率密度）は「その付近にどれだけ人が集まっているか」の目安にすぎず、確率そのものではない。範囲を横幅として切り取り、その下の面積を計算して初めて「その範囲に入る確率」になる。", "vs": "「曲線の高さが確率」だと誤解しやすいが、高さ（確率密度）はあくまで密度、面積にして初めて確率になる。サイコロのような飛び飛びの値では棒の高さそのものが確率だったが、連続的な値ではその感覚のままだと誤る。", "why_asked": "身長・体重・時間・測定誤差など、実務で扱う多くの値は連続的。「1点の確率は0」を知らないと、正規分布のグラフを見て高さを確率だと勘違いしたり、「ぴったりの値の確率」を求めようとして計算が破綻したりする。", "usecase": "正規分布を使った「テストの点数が70点から80点のあいだに入る割合」の計算、品質検査で「規格の範囲内に収まる確率」の計算、天気予報の「気温が20〜25度になる確率」のような表現。", "opt": ["正解。連続的な値の分布では、範囲にあたる曲線の下の面積が、その範囲の確率を表す。", "曲線の一番高い場所の高さは、値が密集している目安（確率密度）にすぎず、それ自体が確率を表すわけではない。", "曲線と横軸が交わる点の数は分布の形の特徴にすぎず、範囲の確率の大きさとは直接関係がない。", "曲線の傾きの急さは値の変わり方の速さを示すだけで、範囲に入る確率の大きさを直接表すものではない。"]}'),

  ('stats2-q12', '確率と分布',
   'コインを5回連続で投げて、5回とも表が出た。「そろそろ裏が出やすいはずだ」と思うのは統計的に正しい？',
   NULL::text,
   '["次も表と裏は五分五分のまま", "次は裏の出る確率のほうが高くなる", "次は表ではなく必ず裏になる", "表の出る確率がこれまで以上に上がる"]',
   0, '[0]', 'single',
   '{"asked": "「これまでの結果」が「次の結果」に影響するかどうかという、独立という考え方。", "point": "コインの1回1回の結果はそれぞれ独立。前に何が出たかは、次に何が出る確率にまったく影響しない。", "kid": "コインには「さっき何を出したか」を覚えておく記憶がない。だから1回目に表が出ようが5回連続で表が出ようが、6回目に表が出る確率も裏が出る確率も、変わらずどちらも1/2のまま。「そろそろ裏のはず」と考えるのは、実際には起きない現象を期待してしまう思い込み。", "eg": "サイコロを転がすたびに、サイコロが前回の目を覚えていて次の出方を調整する、なんてことはない。毎回まっさらな状態から転がる。コインも同じで、5回表が出たあとの6回目は、1回目とまったく同じ条件で振り出しに戻っている。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><circle cx=\"30\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><text x=\"30\" y=\"52\" fill=\"#e8eaf0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">表</text><circle cx=\"82\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><text x=\"82\" y=\"52\" fill=\"#e8eaf0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">表</text><circle cx=\"134\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><text x=\"134\" y=\"52\" fill=\"#e8eaf0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">表</text><circle cx=\"186\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><text x=\"186\" y=\"52\" fill=\"#e8eaf0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">表</text><circle cx=\"238\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><text x=\"238\" y=\"52\" fill=\"#e8eaf0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">表</text><circle cx=\"290\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.8\"/><text x=\"290\" y=\"52\" fill=\"#e8eaf0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">？</text><text x=\"170\" y=\"92\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">5回続けて表が出ても</text><text x=\"170\" y=\"112\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">次に裏が出やすくなったりはしない</text><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">次も裏・表は五分五分のまま（コインに記憶はない）</text></svg>", "terms": [["独立", "1回の結果が、他の回の結果や確率にまったく影響を与えないこと"], ["ギャンブラーの誤謬", "「これだけ続いたから、そろそろ逆になるはず」と思い込んでしまう誤り"]], "think": "「5回連続で表」という出来事自体は、36分の1よりずっと小さい珍しい出来事（1/32）ではある。でもそれは「これから5回投げて全部表になる確率」の話であって、「すでに4回表が続いたあとの、5回目の確率」の話ではない。コインの表裏を決めるのは、投げるたびの物理的な条件だけで、過去の結果を参照する仕組みはどこにもない。だから、すでに表が4回続いた状態で5回目を投げても、その1回だけを見れば表も裏も相変わらず1/2ずつ。「そろそろ裏」という感覚は、独立という前提を忘れて、まるでコインに記憶があるかのように考えてしまう思い込みから生まれる。", "vs": "「5回連続で表が出ることは珍しい」というのは正しい。ただしそれは「これから5回投げる前」の話。すでに4回表が出たあとの「次の1回」を考えるときは、話がリセットされて毎回五分五分に戻る、という切り分けが混同されやすい。", "why_asked": "独立という前提を忘れると、ギャンブルで「そろそろ当たるはず」と思い込んで損を重ねたり、逆に「もう出たから次は減るはず」と誤った予測をしたりする。確率変数を正しく扱うための、大事な仕上げの注意点。", "usecase": "ルーレットやコイン投げでの「連続結果は次に影響しない」という判断、品質検査で「不良品が続いたから次は大丈夫」と考えない姿勢、独立な試行を前提にした二項分布の計算そのものの正しさの根拠。", "opt": ["正解。コインの1回1回は独立していて、前の結果は次の確率にまったく影響しない。次も五分五分のまま。", "裏が出る確率が上がると考えるのは、コインに「出した目を覚えておく記憶」があるかのように扱ってしまっている。", "次は必ず裏になるというのは言い過ぎで、6回連続で表になる可能性も依然として残っている（確率は下がるが0ではない）。", "表の確率がさらに上がると考えるのも、独立という前提を無視して「勢いがついている」かのように扱ってしまっている。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
